"const fs = require('fs');
const path = require('path');

const siteDir = 'c:\\Users\\rahat\\OneDrive\\Desktop\\Rahat\\UCSD\\Fall 26\\CSE216\\results\\gemini\\L2\\run-05\\site';
const htmlPath = path.join(siteDir, 'index.html');
const cssPath = path.join(siteDir, 'styles.css');
const jsPath = path.join(siteDir, 'script.js');

console.log('Checking files...');
console.log('index.html exists:', fs.existsSync(htmlPath), 'size:', fs.statSync(htmlPath).size);
console.log('styles.css exists:', fs.existsSync(cssPath), 'size:', fs.statSync(cssPath).size);
console.log('script.js exists:', fs.existsSync(jsPath), 'size:', fs.statSync(jsPath).size);

const html = fs.readFileSync(htmlPath, 'utf8');
const js = fs.readFileSync(jsPath, 'utf8');

// Find all document.getElementById calls in js
const idRegex = /document\.getElementById\(['"]([^'"]+)['"]\)/g;
let match;
const ids = new Set();
while ((match = idRegex.exec(js)) !== null) {
  ids.add(match[1]);
}

console.log('\nTotal getElementById targets found in JS:', ids.size);
let missing = [];
for (const id of ids) {
  if (!html.includes(`id="${id}"`) && !html.includes(`id='${id}'`)) {
    missing.push(id);
  }
}

if (missing.length === 0) {
  console.log('SUCCESS: All', ids.size, 'IDs used in JS exist in index.html!');
} else {
  console.error('MISSING IDs:', missing);
}
"

"const fs = require('fs');
const html = fs.readFileSync('c:\\Users\\rahat\\OneDrive\\Desktop\\Rahat\\UCSD\\Fall 26\\CSE216\\results\\gemini\\L2\\run-05\\site\\index.html', 'utf8');

// Basic unclosed tag check for key semantic tags
const tags = ['html', 'head', 'body', 'header', 'nav', 'main', 'section', 'footer', 'table', 'thead', 'tbody', 'tfoot', 'form'];
tags.forEach(tag => {
  const openCount = (html.match(new RegExp(`<${tag}[\\s>]`, 'gi')) || []).length;
  const closeCount = (html.match(new RegExp(`</${tag}>`, 'gi')) || []).length;
  console.log(`Tag <${tag}>: open=${openCount}, close=${closeCount}, balanced=${openCount === closeCount}`);
});
